// Alias para el tipo de byte
using byte = uint8_t;
using data_chunk = std::vector<byte>;

// // Error básico de lectura.
// struct byte_reader_error {
//     std::string message;
// };

enum class byte_reader_error {
    skip_past_end_of_buffer,
    read_past_end_of_buffer,
};

std::string error_to_string(byte_reader_error error) {
    switch (error) {
        case byte_reader_error::skip_past_end_of_buffer:
            return "skip past end of buffer";
        case byte_reader_error::read_past_end_of_buffer:
            return "read past end of buffer";
    }
}

template <typename T>
using expect = nonstd::expected<T, byte_reader_error>;

// `byte_reader` para manipular un `std::span<byte>` y realizar operaciones de lectura.
struct byte_reader {
    // Constructor que toma un span sobre el buffer de datos.
    explicit
    byte_reader(std::span<const byte> buffer)
        : buffer_(buffer)
        , position_(0)
    {}

    // Retorna el tamaño del buffer.
    size_t size() const { return buffer_.size(); }

    // Retorna la posición actual de lectura.
    size_t position() const { return position_; }

    // Salta `count` bytes desde la posición actual.
    expect<void> skip(size_t count) {
        if (position_ + count > buffer_.size()) {
            return nonstd::unexpected(byte_reader_error::skip_past_end_of_buffer);
        }
        position_ += count;
        return {};
    }

    // Lee un byte desde la posición actual.
    expect<byte> read_byte() {
        if (position_ >= buffer_.size()) {
            return nonstd::unexpected(byte_reader_error::read_past_end_of_buffer);
        }
        return buffer_[position_++];
    }

    // Lee una cantidad fija de bytes.
    expect<std::span<const byte>> read_bytes(size_t size) {
        if (position_ + size > buffer_.size()) {
            return nonstd::unexpected(byte_reader_error::read_past_end_of_buffer);
        }
        auto start = position_;
        position_ += size;
        return buffer_.subspan(start, size);
    }

    // Lee un entero en little endian.
    template <typename Integer>
    expect<Integer> read_little_endian() {
        if (position_ + sizeof(Integer) > buffer_.size()) {
            return nonstd::unexpected(byte_reader_error::read_past_end_of_buffer);
        }
        Integer value = 0;
        std::memcpy(&value, buffer_.data() + position_, sizeof(Integer));
        position_ += sizeof(Integer);
        return value;
    }

    // Lee un entero en big endian.
    template <typename Integer>
    expect<Integer> read_big_endian() {
        if (position_ + sizeof(Integer) > buffer_.size()) {
            return nonstd::unexpected(byte_reader_error::read_past_end_of_buffer);
        }
        Integer value = 0;
        for (size_t i = 0; i < sizeof(Integer); ++i) {
            value = (value << 8) | buffer_[position_++];
        }
        return value;
    }

    expect<uint64_t> read_variable_little_endian() {
        constexpr uint8_t varint_two_bytes = 0xfd;
        constexpr uint8_t varint_four_bytes = 0xfe;
        constexpr uint8_t varint_eight_bytes = 0xff;

        auto const value_exp = read_byte();
        if ( ! value_exp) {
            return nonstd::unexpected(value_exp.error());
        }
        auto const value = *value_exp;

        switch (value) {
            case varint_eight_bytes: {
                fmt::print("read_variable_little_endian() reading 8 bytes\n");
                return read_little_endian<uint64_t>();
            }
            case varint_four_bytes: {
                fmt::print("read_variable_little_endian() reading 4 bytes\n");
                return read_little_endian<uint32_t>();
            }
            case varint_two_bytes: {
                fmt::print("read_variable_little_endian() reading 2 bytes\n");
                return read_little_endian<uint16_t>();
            }
            default: {
                fmt::print("read_variable_little_endian() reading 1 byte\n");
                return value;
            }
        }
    }

    // size_t read_size_little_endian() {
    //     auto const size = read_variable_little_endian();

    //     // This facilitates safely passing the size into a follow-on reader.
    //     // Return zero allows follow-on use before testing reader state.
    //     if (size <= max_size_t) {
    //         return static_cast<size_t>(size);
    //     }

    //     invalidate();
    //     return 0;
    // }

    expect<size_t> read_size_little_endian() {
        constexpr uint64_t max_size_t = std::numeric_limits<size_t>::max();

        auto const size_exp = read_variable_little_endian();
        if ( ! size_exp) {
            return nonstd::unexpected(size_exp.error());
        }
        auto const size = *size_exp;
        if (size <= max_size_t) {
            return size_t(size);
        }
        //Es eso posible?
        return nonstd::unexpected(byte_reader_error::read_past_end_of_buffer);
    }



    // Lee una estructura empaquetada.
    template <typename T>
    expect<T> read_packed() {
        static_assert(std::is_trivially_copyable_v<T>, "T must be trivially copyable.");
        if (position_ + sizeof(T) > buffer_.size()) {
            return nonstd::unexpected(byte_reader_error::read_past_end_of_buffer);
        }
        T value;
        std::memcpy(&value, buffer_.data() + position_, sizeof(T));
        position_ += sizeof(T);
        return value;
    }

    // Verifica si ya se leyó todo el buffer.
    bool is_exhausted() const {
        return position_ >= buffer_.size();
    }

    size_t bytes_left() const {
        return buffer_.size() - position_;
    }

    void print_hex() const {
        fmt::print("{}", bytes2hex(buffer_));
    }

    void print_remaining() const {
        fmt::print("{}", bytes2hex(buffer_.subspan(position_)));
    }

private:
    std::span<const byte> buffer_;  // Buffer de datos sobre el cual se hace la lectura.
    size_t position_;               // Posición actual de lectura en el buffer.
};



// Test parsing of block # 168502

void parse_tx(kth::data_chunk const& txs_data) {
    std::string message = fmt::format("before parsing transactions");
    print_memory_usage(message);
    fmt::print("data size: {}\n", txs_data.size());

    kth::domain::chain::transaction tx;
    kth::domain::entity_from_data(tx, txs_data);
    message = fmt::format("after parsing transactions");
    print_memory_usage(message);
    auto const valid = tx.is_valid();

    if ( ! valid) {
        // Should not happen
        fmt::print("****** INVALID TRANSACTION ******\n");
        std::terminate();
    }
    auto const data = tx.to_data();
    fmt::print("data size: {}\n", data.size());
    fmt::print("hex data: {}\n", bytes2hex(data));
    fmt::print("------------------------------------------------\n");
}

